package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import jakarta.validation.Valid;
import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.RequestBody;

@Validated
public class BuildOwner {

    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
            Out<Boolean> sharesHousehold) {
        Owner owner = ownerMapper.toOwner(request);
        // Establish the raw registration date, defaulting an absent one to the server
        // date. NormalizeOwnerRegistrationDate later rolls a weekend forward to a
        // business day; derived values (membership number, daily limit) read it back
        // off the owner, so they see the adjusted date regardless.
        if (owner.getRegistrationDate() == null) {
            owner.setRegistrationDate(LocalDate.now());
        }
        built.set(owner);
        // sharesHousehold is a create-time flag, not an Owner field; republish it for
        // AssignHousehold. Absent in the body means false.
        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.net.URI;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;

public class RespondWithOwnerCreated {

    public void service(@Val Owner owner, OwnerMapper ownerMapper,
            ObjectResponse<ResponseEntity<OwnerDto>> response) {
        OwnerDto dto = ownerMapper.toOwnerDto(owner);
        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * The registration date must fall on a business day. Whatever the owner's effective
 * registration date — supplied in the request or defaulted by {@link BuildOwner} — a
 * Saturday rolls forward two days and a Sunday one day to the following Monday, stored
 * back on the owner. Weekdays are left unchanged. Everything derived from the
 * registration date (the membership number's year segment, the daily create-limit)
 * reads it back off the owner, so it sees the adjusted date.
 */
public class NormalizeOwnerRegistrationDate {

    public void service(@Val Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        DayOfWeek day = registrationDate.getDayOfWeek();
        if (day == DayOfWeek.SATURDAY) {
            owner.setRegistrationDate(registrationDate.plusDays(2));
        } else if (day == DayOfWeek.SUNDAY) {
            owner.setRegistrationDate(registrationDate.plusDays(1));
        }
    }
}

